  bash rex12.sh --client                显示节点信息、VLESS 链接和终端二维码
  bash rex12.sh --status                查看服务状态
  bash rex12.sh --start                 启动/重启，并设置开机自启
  bash rex12.sh --stop                  停止 Rust 服务
  bash rex12.sh --logs                  查看服务日志
  bash rex12.sh --network               仅BBR/FQ、3F2网络参数与恢复
  bash rex12.sh --micro-menu            28项控制中心
  bash rex12.sh --micro-28              --apply-defaults 的兼容别名
  bash rex12.sh --cleanup-menu          设置每日磁盘清理
  bash rex12.sh --cleanup-preview       预览清理范围
  bash rex12.sh --cleanup               立即清理
  bash rex12.sh --host-status           查看主机实际运行值
  bash rex12.sh --host-recover          恢复未完成的主机/网卡事务
